{
  "scenes": [
    {
      "scene_id": "S1",
      "name": "杂乱桌面",
      "setting": "工位全景，桌面堆着杯子、快递盒、票据、两台设备",
      "mood": "闷、手忙脚乱"
    },
    {
      "scene_id": "S2",
      "name": "整理动作",
      "setting": "俯拍桌面，手依次拿走杂物、归位抽屉",
      "mood": "干净、有节奏"
    },
    {
      "scene_id": "S3",
      "name": "清爽开工",
      "setting": "桌面只剩键盘、鼠标、一本笔记本，人坐下开始打字",
      "mood": "安静、专注"
    }
  ],
  "shots": [
    {
      "shot_id": "SH01",
      "scene": "S1",
      "description": "全景固定镜头：主角坐到堆满杂物的工位前，叹气，手指在杯子和快递盒之间犹豫，不知道先动哪个。"
    },
    {
      "shot_id": "SH02",
      "scene": "S1",
      "description": "中近景：主角低头看向桌面，画面轻微手持晃动，字幕打出口播钩子“每天早上坐下第一件事，不是打开电脑”。"
    },
    {
      "shot_id": "SH03",
      "scene": "S2",
      "description": "俯拍特写：手快速把杯子、快递、票据逐件移出画面，每移走一件加一声轻脆音效，节奏稳定。"
    },
    {
      "shot_id": "SH04",
      "scene": "S2",
      "description": "侧拍中景：物品被放进抽屉、文件袋，动作干净利落，屏幕上标注“一物一位”，不打乱现有工作动线。"
    },
    {
      "shot_id": "SH05",
      "scene": "S3",
      "description": "俯拍定格：桌面只剩键盘、鼠标、一本笔记本，构图留白，字幕“三分钟，把决定提前做完”。"
    },
    {
      "shot_id": "SH06",
      "scene": "S3",
      "description": "过肩镜头：主角直接伸手敲键盘开始工作，无停顿，画面渐稳，结尾字幕“专注力自然留在工作本身”。"
    }
  ]
}
